pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash, address guesser, uint256 amount1, uint256 amount2) public {
        // Keep amounts in a reasonable range; allow zero to capture the bug's 0 ether path
        amount1 = bound(amount1, 0, 100 ether);
        amount2 = bound(amount2, 0, 100 ether);
        vm.assume(guesser != address(0));
        vm.assume(guesser != address(this));
        vm.assume(guesser != address(c));

        address other = address(uint160(uint256(keccak256(abi.encode(guesser, "other")))));
        vm.assume(other != address(0) && other != guesser && other != address(this) && other != address(c));

        // fund actors
        vm.deal(guesser, amount1);
        vm.deal(other, amount2);

        // guesser locks in a guess
        vm.prank(guesser);
        c.lockInGuess{value: amount1}(hash);

        // another actor locks in a guess
        vm.prank(other);
        c.lockInGuess{value: amount2}(hash);

        // The contract must hold at least the sum of ether paid by the two guessers
        assertTrue(address(c).balance >= amount1 + amount2);
    }
}

