        if (succeeded) {
            // If it succeeded (buggy), the guess must have been overwritten to hash2
            // We need to settle to verify the guess
            // The block getter for guesses is a public struct, so we can read the field directly
            // The mapping is guesses, which returns the struct, but mapping getter takes address
            (uint256 blockNumber, bytes32 storedHash) = c.guesses(actor);
            assertTrue(storedHash == hash2);
        } else {
            // If it reverted (original), the original guess must remain hash1
            (uint256 blockNumber, bytes32 storedHash) = c.guesses(actor);
            assertTrue(storedHash == hash1);
        }
    }
}

