pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash) public {
        // The fuzzer supplies a hash that a user will lock in.
        // Create a user with enough ether to participate.
        address user = makeAddr("user");
        vm.deal(user, 2 ether);

        // User locks in the guess with 1 ether.
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(hash);

        // We need the block used for the answer to be in the past and its blockhash available.
        // The guess lock sets block = current + 1. We mine past that block so blockhash is available.
        // Use vm.roll to move to a block where the guess block is strictly in the past and has a blockhash.
        // The latest block is now block.number after lockInGuess.
        // The required block for answer is block.number (which was current+1 at lock time).
        // We need at least one more block after that so blockhash is available (blockhash only for last 256 blocks).
        // Move 2 blocks ahead to ensure the block number used is < current and within 256.
        vm.roll(block.number + 2);

        // Record balance before settlement.
        uint256 contractBalanceBefore = address(c).balance;
        uint256 userBalanceBefore = user.balance;

        // Settle as the user.
        vm.prank(user);
        c.settle();

        uint256 contractBalanceAfter = address(c).balance;
        uint256 userBalanceAfter = user.balance;

        // If the guess was correct, the user received a transfer.
        // The transfer amount is exactly contractBalanceBefore - contractBalanceAfter.
        // The reference transfers 2 ether, the bug transfers 1 ether.
        // The property: if user balance increased, the contract balance decreased by exactly 2 ether.
        // This holds for every input in the reference, but fails in the bug when guess is correct.
        // We assert: either user didn't win (balance unchanged), or the decrease is exactly 2 ether.
        bool won = userBalanceAfter > userBalanceBefore;
        assertTrue(!won || contractBalanceBefore - contractBalanceAfter == 2 ether);
    }
}

